package com.verireview.generation.dto;

import java.util.List;

/**
 * One clarifying question generated by the backend from steps 1–2 of the
 * Generate wizard. The backend is the source of truth: the frontend renders
 * exactly these questions and never invents its own defaults.
 *
 * @param id stable question id used as the answer key
 * @param prompt user-facing question text
 * @param help optional explanation of why the answer matters
 * @param type input widget
 * @param required whether a blank answer blocks the plan step
 * @param allowSkip whether an explicit "Ask me later" answer is acceptable
 * @param secret true when the value must never be persisted or echoed
 * @param options choices for {@code CHOICE} (empty for text/yes-no)
 */
public record GenerationQuestion(
    String id,
    String prompt,
    String help,
    GenerationQuestionType type,
    boolean required,
    boolean allowSkip,
    boolean secret,
    List<QuestionOption> options) {

  public record QuestionOption(String value, String label) {
  }
}
